import{af as e,z as a,J as r,ab as o}from"./chunks/framework.C1QHhBQn.js";const i="/docs/pr/40/images/devices/general/led-rh2-charging.svg",g=JSON.parse('{"title":"RTK device LED indicators","description":"","frontmatter":{"aside":true},"headers":[],"relativePath":"guides/rtk-leds.md","filePath":"guides/rtk-leds.md"}'),n={name:"guides/rtk-leds.md"};function s(d,t,l,h,c,p){return a(),r("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1794235425000"},[...t[0]||(t[0]=[o('<h1 id="rtk-device-led-indicators" tabindex="-1">RTK device LED indicators <a class="header-anchor" href="#rtk-device-led-indicators" aria-label="Permalink to &quot;RTK device LED indicators&quot;">​</a></h1><p><strong>Handheld RH2 and Vehicle RTK do not use the same LED display.</strong> Choose the model below. A shared RTK capability does not imply the same indicators or application controls.</p><h2 id="handheld-rtk-rh2" tabindex="-1">Handheld RTK (RH2) <a class="header-anchor" href="#handheld-rtk-rh2" aria-label="Permalink to &quot;Handheld RTK (RH2)&quot;">​</a></h2><p>RH2 uses an RGB status display in the standard firmware. Application-controlled lights can provide separate feedback, so first check whether you are looking at charging/status or at a running application&#39;s indication. See the <a href="/docs/pr/40/devices/rtk/handheld/external#front">RH2 exterior guide</a> for the enclosure layout.</p><h3 id="charging-status" tabindex="-1">Charging status <a class="header-anchor" href="#charging-status" aria-label="Permalink to &quot;Charging status&quot;">​</a></h3><p>The standard RGB charging display changes colour with the approximate battery level:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Charging status colour</th></tr></thead><tbody><tr><td>Below 30%</td><td>Red</td></tr><tr><td>30% to below 70%</td><td>Orange</td></tr><tr><td>70% to below 90%</td><td>Yellow-green</td></tr><tr><td>90% or more</td><td>Green</td></tr></tbody></table><p>Brightness varies in steps about every half-second while charging below approximately 99%. At about 99% or above, that variation stops. Green starts at about 90%; it is not an exact full-battery indication or proof of an RTK fix.</p><figure><img src="'+i+'" alt="RH2 charging colours: red below 30 percent, orange from 30 to below 70, yellow-green from 70 to below 90, green at 90 or more. Brightness varies below about 99 percent and is steady at about 99 percent or more." tabindex="0"><figcaption>RH2 charging colours: red below 30 percent, orange from 30 to below 70, yellow-green from 70 to below 90, green at 90 or more. Brightness varies below about 99 percent and is steady at about 99 percent or more.</figcaption></figure><p>Do not apply the four-bar, 95% charging rule from Pro3 or the older ProN/Zero/Enviro guides to RH2.</p><h3 id="off-charge-status" tabindex="-1">Off-charge status <a class="header-anchor" href="#off-charge-status" aria-label="Permalink to &quot;Off-charge status&quot;">​</a></h3><p>When armed and active, the standard status display can reflect positioning state and low battery. A configured resting colour takes precedence over that default indication, and an inactive device normally turns the status display off. Applications and alarms can also control the lights.</p><p>For this reason, a green or red light by itself is not a reliable statement of RTK accuracy, upload success or a hardware fault. Check the application&#39;s positioning/accuracy information and the latest successful communication.</p><h3 id="application-controlled-feedback" tabindex="-1">Application-controlled feedback <a class="header-anchor" href="#application-controlled-feedback" aria-label="Permalink to &quot;Application-controlled feedback&quot;">​</a></h3><p>The <a href="/docs/pr/40/devices/api/sdks/toit/applications/survey/#cloud-submission">Survey application</a> flashes green for a successfully submitted survey point and red for a submission error. Those are application events, not the charging colour table above. Other applications can choose different patterns.</p><h2 id="vehicle-rtk-vtrtk" tabindex="-1">Vehicle RTK (VTRTK) <a class="header-anchor" href="#vehicle-rtk-vtrtk" aria-label="Permalink to &quot;Vehicle RTK (VTRTK)&quot;">​</a></h2><p>VTRTK has four indicators in the standard firmware, not RH2&#39;s RGB status display. It uses the shared battery-bar and vehicle connection patterns below. Indicator colours and physical orientation should be checked for the supplied hardware revision.</p><h3 id="normal-battery-display" tabindex="-1">Normal battery display <a class="header-anchor" href="#normal-battery-display" aria-label="Permalink to &quot;Normal battery display&quot;">​</a></h3><p>A short status-button press normally shows the battery level briefly. The four indicators use these approximate bands:</p><table tabindex="0"><thead><tr><th>Battery level</th><th>Normal battery display</th></tr></thead><tbody><tr><td>Below 20%</td><td>First indicator flashes when showing status off charge</td></tr><tr><td>20% to below 40%</td><td>1 indicator</td></tr><tr><td>40% to below 60%</td><td>2 indicators</td></tr><tr><td>60% to below 80%</td><td>3 indicators</td></tr><tr><td>80% or more</td><td>4 indicators</td></tr></tbody></table><p>These bands apply to the normal battery display only. Startup, alerts and application-controlled patterns can use the same lights for a different reason. Four lights are not an exact 100% reading.</p><h3 id="charging-and-ignition" tabindex="-1">Charging and ignition <a class="header-anchor" href="#charging-and-ignition" aria-label="Permalink to &quot;Charging and ignition&quot;">​</a></h3><ul><li>Below about 95%, the highest lit battery indicator blinks, roughly one second on and one second off. At very low charge, the first indicator blinks.</li><li>At about 95% or above, the normal charging display becomes steady. This means a high charge level, not an exact 100% reading.</li><li>When unplugged and resting, the lights normally go out after any temporary status display finishes. A button press, startup or other activity can still light them.</li></ul><p>These are the standard battery-bar patterns. They are not the RGB charging colours used by RH2.</p><p>After a status-button press, the vehicle connection display flashes logical indicators 1–2 for ignition high and 3–4 for charging, in five cycles of about 0.3 seconds on and 0.2 seconds off. Both pairs can flash together. These logical numbers do not establish left-to-right positions on the case.</p><p>External power and active charging are different states. Do not treat an unlit charging pair as proof that there is no external power. The <a href="/docs/pr/40/guides/vehicle-leds#vehicle-connection-status">vehicle connection diagram</a> illustrates the logical pairs, not the enclosure colours.</p><h3 id="startup-and-other-patterns" tabindex="-1">Startup and other patterns <a class="header-anchor" href="#startup-and-other-patterns" aria-label="Permalink to &quot;Startup and other patterns&quot;">​</a></h3><p>Startup and alerts can temporarily use the same indicators. Check the latest successful communication after startup, and use the instructions for any custom application that controls the lights. RH2&#39;s RGB colours and Survey feedback are not automatically VTRTK features.</p><h2 id="other-rtk-generations" tabindex="-1">Other RTK generations <a class="header-anchor" href="#other-rtk-generations" aria-label="Permalink to &quot;Other RTK generations&quot;">​</a></h2><p>Older RTK handhelds and base stations have different displays. Use their <a href="/docs/pr/40/devices/history/">legacy documentation</a> or <a href="https://lightbug.io/contact/" target="_blank" rel="noreferrer">contact support</a> with the product code, device ID and revision. Choose a different family in the <a href="/docs/pr/40/guides/leds">LED guide</a>.</p>',30)])])}const f=e(n,[["render",s]]);export{g as __pageData,f as default};
